'use strict';
const $=s=>document.querySelector(s),P=SG.platforms,KEY='shiguang.library.v1';
const examples=[
 ['可视化理解线性代数：从向量到线性变换','https://www.youtube.com/watch?v=fNk_zzaMoSs','youtube','video',['数学','可视化'],'用图形重新认识线性代数，给抽象的公式找到直觉。','Linear\nalgebra','THE BEAUTY OF MATHEMATICS','#e4e9df','#50684b'],
 ['Python 官方教程：从第一行代码开始','https://docs.python.org/zh-cn/3/tutorial/','other','article',['编程','Python'],'在阅读中做练习，用一个个小程序建立基础。','Hello,\nPython.','LEARN BY MAKING','#eae6da','#8a7956'],
 ['收藏整理示例：给碎片知识建立一张地图','https://www.zhihu.com/collections','zhihu','article',['知识管理','学习方法'],'示例条目：用主题整理知识，让收藏真正服务于学习。','Connect\nthe dots.','A MAP OF YOUR MIND','#e3e9e9','#628181'],
 ['B 站学习清单：从收藏到实际行动','https://www.bilibili.com','bilibili','video',['学习方法','编程'],'示例条目：把收藏的视频加入待阅读，每次只学一个小主题。','一小步，\n也算数。','ONE THING AT A TIME','#eee7dc','#9c8464'],
 ['LINUX DO：把值得反复读的帖子放在一起','https://linux.do','linuxdo','article',['技术社区','编程'],'示例条目：采集书签页中已经加载的话题，再给它们加上标签。','Ideas,\nshared.','THE OPEN COMMUNITY','#e8e7dc','#7e805b'],
 ['GitHub 上的计算机科学学习路径','https://github.com/ossu/computer-science','github','resource',['编程','学习方法'],'一个开放的计算机科学学习路径，适合慢慢探索。','Build.\nLearn. Repeat.','STAY CURIOUS','#e4e8dd','#627651'],
 ['小红书灵感收集：写下你为什么收藏','https://www.xiaohongshu.com','xiaohongshu','article',['知识管理','生活灵感'],'示例条目：保存链接时加上一句自己的想法，下次更容易找回。','灵感，\n不再走散。','KEEP WHAT INSPIRES YOU','#eee2db','#a47e70'],
 ['抖音学习片段：让喜欢的内容可检索','https://www.douyin.com','douyin','video',['生活灵感','学习方法'],'示例条目：把收藏或喜欢页上的学习内容集中到自己的书架。','Little\ndiscoveries.','MAKE ROOM FOR IDEAS','#e6e3ea','#82728b']
].map((a,i)=>({...SG.normalize({title:a[0],url:a[1],platform:a[2],type:a[3],tags:a[4],notes:a[5],id:'demo-'+i,read:i===1||i===5,starred:i===0||i===4,createdAt:new Date(Date.now()-i*86400000).toISOString()}),art:a[6],caption:a[7],cover:a[8],ink:a[9]}));
let items=[],demo=!localStorage.getItem(KEY),storageFailed=false;try{const parsed=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(parsed))throw Error();items=parsed.map(SG.normalize).filter(Boolean)}catch{storageFailed=true;demo=false}
let persistedIds=new Set(items.map(x=>x.id));
let state={q:'',platform:'all',view:'all',tag:'all',type:'all',sort:'new'},list=matchMedia('(max-width:700px)').matches,detailId=null,toastTimer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const data=()=>demo?examples:items;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(){try{const latest=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(latest))throw Error();items=SG.merge(items,latest.filter(x=>!persistedIds.has(x.id))).items;localStorage.setItem(KEY,JSON.stringify(items));persistedIds=new Set(items.map(x=>x.id));storageFailed=false;window.dispatchEvent(new Event('shiguang-local-change'));return true}catch{storageFailed=true;toast('浏览器保存失败，请立即导出备份；当前更改只保留在此页面。');return false}}
function badge(k){const p=P[k]||P.other;return `<span class="platform-badge" style="--pc:${p.color};--pb:${p.bg}">${p.icon}</span>`}
function resetFilters(){state={q:'',platform:'all',view:'all',tag:'all',type:'all',sort:'new'};$('#search').value='';$('#type-filter').value='all';$('#sort').value='new'}
function render(){const filterCount=[state.platform,state.view,state.type].filter(value=>value!=='all').length+(state.sort!=='new'?1:0);$('#filter-toggle').textContent=filterCount?'筛选 · '+filterCount:'筛选';$('#grid-view').classList.toggle('active',!list);$('#list-view').classList.toggle('active',list);$('#mobile-platform').value=state.platform;$('#mobile-view').value=state.view;const all=data(),filtered=SG.filter(all,state),unread=all.filter(x=>!x.read).length;$('#main-nav').innerHTML=[['all','▧','全部收藏',all.length],['unread','◷','稍后阅读',unread],['starred','☆','特别关注',all.filter(x=>x.starred).length],['read','✓','已经读过',all.length-unread]].map(([k,icon,t,n])=>`<button data-view="${k}" class="${state.view===k&&state.platform==='all'?'active':''}"><span class="nav-symbol">${icon}</span>${t}<span class="nav-count">${n}</span></button>`).join('');$('#platform-nav').innerHTML=Object.entries(P).map(([k,p])=>`<button data-platform="${k}" class="${state.platform===k?'active':''}">${badge(k)}${p.name}<span class="nav-count">${all.filter(x=>x.platform===k).length}</span></button>`).join('');const countPlatforms=new Set(all.map(x=>x.platform)).size;$('#stats').innerHTML=[['收下的灵感',all.length,'条收藏','▧'],['等待被发现',unread,'条待阅读','◷'],['已经有收获',all.length-unread,'条已读','✓'],['汇集的来源',countPlatforms,'个平台','⌘']].map(a=>`<div class="stat"><div class="stat-label">${a[0]}<span>${a[3]}</span></div><strong>${a[1]}</strong><small>${a[2]}</small></div>`).join('');const names={all:'全部收藏',unread:'稍后阅读',starred:'特别关注',read:'已经读过'};const title=state.platform==='all'?names[state.view]:P[state.platform].name;$('#library-title').textContent=title;$('#crumb').textContent=title;$('#page-title').textContent=state.platform==='all'?'好知识，终于在一起。':`来自${P[state.platform].name}的好知识。`;$('#result-count').textContent=`${filtered.length} 条${demo?'示例':''}内容`;const tags=[...new Set(all.flatMap(x=>x.tags))];$('#tag-filters').innerHTML=['all',...tags].map(t=>`<button class="${state.tag===t?'active':''}" data-tag="${esc(t)}">${t==='all'?'全部标签':'# '+esc(t)}</button>`).join('');$('#demo-notice').hidden=!demo;$('#demo-notice').style.display=demo?'flex':'none';$('#cards').className='cards'+(list?' list':'');$('#cards').innerHTML=filtered.map((x,i)=>{const p=P[x.platform],type={video:'视频',article:'文章',resource:'资源'}[x.type];return `<article class="card" style="animation-delay:${Math.min(i,8)*30}ms"><a class="cover" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer" style="--cover:${x.cover||p.bg};--art:${x.ink||p.color};width:${list?'':'100%'}" aria-label="打开原内容：${esc(x.title)}">${SG.thumbnailFor(x)?`<img class="cover-image" src="${esc(SG.thumbnailFor(x))}" alt="" loading="lazy" referrerpolicy="no-referrer">`:""}<span class="cover-type">${x.type==='video'?'▷':'▤'} ${type}</span>${x.read?'<span class="read-marker">✓ 已读</span>':''}<span class="cover-art">${esc(x.art||p.name).replace(/\n/g,'<br>')}<small>${esc(x.caption||'SAVED FOR A CURIOUS MIND')}</small></span></a><div class="card-body"><div class="source-line">${badge(x.platform)}<span>${p.name}${x.author?' · '+esc(x.author):''}</span><span class="kind">${demo?'示例内容':type}</span></div><a class="card-title" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a><p class="card-desc">${esc(x.notes||'写下一句收藏的理由，方便下次找回。')}</p><div class="card-tags">${x.tags.slice(0,3).map(t=>`<button class="tag" data-tag="${esc(t)}"># ${esc(t)}</button>`).join('')}</div><div class="card-bottom"><span>${new Date(x.createdAt).toLocaleDateString('zh-CN')} 收下</span><div><button data-edit="${esc(x.id)}" aria-label="编辑 ${esc(x.title)}">编辑</button><button class="delete-card" data-delete="${esc(x.id)}" aria-label="删除 ${esc(x.title)}">删除</button><button data-detail="${esc(x.id)}" aria-label="详情 ${esc(x.title)}">详情</button><button data-star="${esc(x.id)}" aria-label="${x.starred?'取消特别关注':'特别关注'}">${x.starred?'★':'☆'}</button><button data-read="${esc(x.id)}">${x.read?'已读 ✓':'标为已读'}</button></div></div></div></article>`}).join('');$('#empty').hidden=filtered.length>0;$('#empty-copy').textContent=all.length?'试试其他关键词，或换个平台、标签找找。':'添加一条链接，或把平台上的收藏带进来。';$('#empty-demo').hidden=demo;}
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close();detailId=null}
function form(item){const edit=!!item;openModal(edit?'编辑这条收藏':'收下一束灵感',`<form id="item-form">${edit?'':'<button type="button" class="paste-link" id="paste-link">▣ 粘贴链接</button>'}<label class="field">网页链接<input name="url" type="url" required placeholder="粘贴 https:// 开头的链接" value="${esc(item?.url||'')}"></label><label class="field">标题<input name="title" required maxlength="500" placeholder="给这条知识起个容易找到的名字" value="${esc(item?.title||'')}"></label><div class="form-row"><label class="field">来源<select name="platform"><option value="auto">根据链接自动识别</option>${Object.entries(P).map(([k,p])=>`<option value="${k}" ${item?.platform===k?'selected':''}>${p.name}</option>`).join('')}</select></label><label class="field">类型<select name="type"><option value="auto">自动判断</option>${[['article','文章'],['video','视频'],['resource','资源']].map(([k,t])=>`<option value="${k}" ${item?.type===k?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">分类 / 标签（选填）<input name="tags" placeholder="用逗号分隔，例如：编程，学习方法" value="${esc(item?.tags.join('，')||'')}"></label><label class="field">收藏原因 / 笔记（选填）<textarea name="notes" placeholder="当时为什么想收藏它？">${esc(item?.notes||'')}</textarea></label><p class="help">链接、标题、标签和笔记保存在当前浏览器。添加真实收藏后会退出示例模式。</p><p class="error" id="form-error"></p><div class="modal-actions"><button class="outline" type="button" id="cancel-form">取消</button><button class="primary" type="submit">${edit?'保存修改':'放进知识库'}</button></div></form>`);$('#cancel-form').onclick=closeModal;if(!edit)$('#paste-link').onclick=pasteLink;$('#item-form').onsubmit=e=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.target));if(raw.platform==='auto')delete raw.platform;if(raw.type==='auto')delete raw.type;const x=SG.normalize({...item,...raw});if(!x){$('#form-error').textContent='请输入有效的 http 或 https 网页链接。';return}if(items.some(y=>y.id!==item?.id&&SG.canonical(y.url)===x.url)){$('#form-error').textContent='这条链接已经在知识库里了。';return}if(edit&&!demo)items=items.map(y=>y.id===item.id?x:y);else items=[x,...items];demo=false;save();closeModal();render();toast(edit?'收藏已更新':'已收下这束灵感')};}
function detail(id){const x=data().find(x=>x.id===id);if(!x)return;detailId=id;openModal(x.title,`<div class="detail-head">${badge(x.platform)} ${P[x.platform].name} · ${x.read?'已经读过':'稍后阅读'} ${demo?'· 示例内容':''}</div><p class="help">${esc(x.tags.map(t=>'# '+t).join('　'))}</p><p class="note-preview">${esc(x.notes||'还没有笔记。写下收藏的原因，下次找它会更容易。')}</p><a class="detail-url" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.url)} ↗</a><p class="help">${demo?'这是示例内容，部分链接指向平台首页。':'点击链接在原平台阅读；阅读完成后可手动标记为已读。'}</p><div class="modal-actions"><button class="danger" id="delete-item">删除</button><button class="outline" id="edit-item">编辑笔记</button><button class="primary" id="toggle-read">${x.read?'改为未读':'标为已读'}</button></div>`);$('#edit-item').onclick=()=>form(x);$('#toggle-read').onclick=()=>{x.read=!x.read;if(!demo)save();render();detail(id)};$('#delete-item').onclick=()=>confirmDelete(id,true);}
function confirmDelete(id,fromDetail=false){const x=data().find(x=>x.id===id);if(!x)return;openModal('删除这条收藏？',`<p class="help">${esc(x.title)}<br>只会从拾光移除，不会影响原平台的收藏。</p><div class="modal-actions"><button class="outline" id="cancel-delete">取消</button><button class="primary" id="confirm-delete">确认删除</button></div>`);$('#cancel-delete').onclick=()=>fromDetail?detail(id):closeModal();$('#confirm-delete').onclick=()=>{if(demo){toast('示例内容无需删除，进入空白知识库即可');closeModal();return}const previous=items;items=items.filter(y=>y.id!==id);if(!save()){items=previous;return}closeModal();render();toast('已删除收藏')};}

function download(name,content,type='application/json'){if(window.ShiguangNative?.postMessage){window.ShiguangNative.postMessage(JSON.stringify({name,content,type}));return}const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){download(`拾光备份-${new Date().toLocaleDateString('sv-SE')}.json`,JSON.stringify({version:1,exportedAt:new Date().toISOString(),items},null,2));toast(window.ShiguangNative?'请在系统文件窗口选择备份保存位置':`已导出 ${items.length} 条真实收藏${demo?'（不含示例）':''}`)}
async function sources(){openModal('让散落的收藏，慢慢归来。',`<p class="help">先安装收藏扩展，以后在网页按住空格再按 S，或右键选择「收藏到拾光…」，即可打开收藏窗口。分类和原因均可留空，不用打开本网站。下次打开这里，快捷收藏会自动归入知识库。未登录时在同一浏览器内归档；网站、扩展和 App 用同一邮箱登录后可跨设备自动同步。它不会自动读取平台账号的全部收藏。</p><div class="data-actions"><button id="import-tab">↓ 导入文件</button><a class="outline" href="collector.zip" download>⌘ 下载 Chrome / Edge 一键收藏扩展</a></div><div class="source-grid" style="margin-top:18px">${Object.entries(P).map(([k,p])=>`<div class="source-tile"><h3>${badge(k)}${p.name}</h3><p>${p.hint}</p><small>${k==='luzi'?'待确认具体应用 · 手动导入':'收藏页采集 / 链接导入'}</small><p>${p.home?`<a href="${p.home}" target="_blank" rel="noopener noreferrer">打开平台 ↗</a>`:'可在添加收藏时手动选择此来源'}</p></div>`).join('')}</div><h3 class="subheading">日常只需点一下</h3><p class="help">解压并安装扩展后，将它固定到浏览器工具栏。在 B站、知乎等内容页按住空格再按 S，或在网页右键选择「收藏到拾光…」。弹窗内可选填分类和收藏原因，点击保存后继续浏览。输入框中不会触发空格 + S；也可用 Alt + Shift + S 作为备用。网站未打开时保存在扩展中，打开网站后自动归档。手机安装新版 App 并开启收藏跟随后，点击原 App 的收藏或保存按钮，识别成功会打开分类窗口。分类和原因均可留空，确认后保存并同步。也可使用原 App 的“分享 → 拾光”。</p><h3 class="subheading">旧收藏如何批量带进来？</h3><p class="help">① 解压扩展，在 Chrome / Edge 的扩展管理页打开开发者模式，选择「加载已解压的扩展程序」。<br>② 在扩展图标的右键菜单打开「选项」，使用批量采集工具。登录原平台，打开收藏 / 书签 / 稍后观看页面；滚动加载需要的条目。<br>③ 点击扩展，选择「采集当前页面」，检查勾选结果后导出 JSON。<br>④ 回到拾光导入该文件。重复链接会自动跳过。网页结构变化可能导致漏采，可手动补充。</p><p class="help">炉子暂按自定义来源处理。采集扩展只读取你主动点击时页面中已加载的链接，不读取 Cookie 或密码，不代表后台自动同步。</p><h3 class="subheading">只想随手存一页？</h3><p class="help">把下面按钮拖到浏览器书签栏；在需要保存的网页点击它，会下载包含网页标题和链接的 JSON，再回到这里导入。部分网页的安全策略可能阻止书签脚本，此时使用扩展或手动添加。</p><a id="bookmarklet" class="bookmarklet">＋ 收到拾光</a><p class="help">接口说明：YouTube 的稍后观看不支持常规播放列表接口读取。<a href="https://developers.google.com/youtube/v3/docs/playlists/list" target="_blank" rel="noopener noreferrer">官方说明 ↗</a></p>`);$('#import-tab').onclick=importDialog;const code=`(()=>{const data={items:[{url:location.href,title:document.title,notes:getSelection().toString().slice(0,5000),createdAt:new Date().toISOString()}]};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='shiguang-page.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)})()`;$('#bookmarklet').href='javascript:'+encodeURIComponent(code);$('#bookmarklet').onclick=e=>{e.preventDefault();toast('请将这个按钮拖到浏览器书签栏，再在原网页点击')};}
function importDialog(){openModal('把收藏带进来',`<p class="help">支持拾光 / 采集扩展导出的 JSON、Chrome / Edge / Firefox 的 HTML 书签，以及 CSV。CSV 表头可使用 title,url,tags,notes 或 标题,链接,标签,笔记；也支持 YouTube Takeout 的 Video Id 列。单文件最多 10 MB。</p><div class="import-zone"><input id="file-input" type="file" accept=".json,.csv,.html,.htm" aria-label="选择导入文件"></div><label class="field">统一指定来源（可选）<select id="import-source"><option value="auto">根据每条链接自动识别</option>${Object.entries(P).map(([k,p])=>`<option value="${k}">${p.name}</option>`).join('')}</select></label><p class="error" id="import-error"></p><div id="import-preview"></div><div class="modal-actions"><button class="outline" id="sample-download">下载 CSV 模板</button><button class="primary" disabled id="confirm-import">导入选中内容</button></div>`);$('#sample-download').onclick=()=>download('拾光导入模板.csv','\uFEFFtitle,url,tags,notes\r\nPython 官方教程,https://docs.python.org/zh-cn/3/tutorial/,编程,从第一章开始\r\n','text/csv');let parsed=[];$('#file-input').onchange=async e=>{parsed=[];$('#confirm-import').disabled=true;$('#import-preview').innerHTML='';$('#import-error').textContent='';const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){$('#import-error').textContent='文件超过 10 MB，请分批导入。';return}try{parsed=SG.parseFile(await file.text(),file.name);if(!parsed.length)throw Error('没有识别到有效的 http / https 链接，请检查文件格式。');$('#import-preview').innerHTML=`<p class="help">识别到 ${parsed.length} 条有效内容，请检查后导入（不含无效链接）。</p><div class="preview-list">${parsed.map((x,i)=>`<label class="preview-item"><input type="checkbox" checked data-import="${i}"><span>${esc(x.title)}<br><small>${esc(x.url)}</small></span></label>`).join('')}</div>`;$('#confirm-import').disabled=false}catch(e){$('#import-error').textContent='无法导入：'+e.message}};$('#confirm-import').onclick=()=>{const selected=[...document.querySelectorAll('[data-import]:checked')].map(el=>parsed[Number(el.dataset.import)]);if(!selected.length){$('#import-error').textContent='请至少选择一条内容。';return}const platform=$('#import-source').value;const result=SG.merge(items,selected.map(x=>platform==='auto'?x:{...x,platform}));items=result.items;demo=false;save();resetFilters();closeModal();render();toast(`已导入 ${result.added} 条，跳过 ${result.duplicates} 条重复链接`)}}
function settings(){openModal('照顾好你的知识库',`<div class="detail-head">${items.length} 条真实收藏 · ${storageFailed?'浏览器存储异常，请先导出':'保存在当前浏览器'}<br><small>在右上角登录后可自动同步到其他设备。离线收藏先存在本机；清除网站数据前请确认同步完成或导出备份。</small></div>${window.ShiguangNative?`<h3 class="subheading">跟随原 App 收藏（试用）</h3><p class="help">Android ${esc(document.documentElement.dataset.appVersion||'')}</p><p class="help" id="auto-capture-status">${esc(document.documentElement.dataset.autoCaptureStatus||'未开启')}</p><p class="help">支持尝试适配小红书、B站、知乎、抖音（含极速版）、YouTube 的可识别界面：点原平台收藏 → 自动尝试分享及复制链接 → 弹出分类窗口 → 你确认保存。必须取得本次原内容链接；失败不会保存摘录或假链接。</p><div class="data-actions"><button data-native-action="enableAutoCapture">开启收藏跟随（试用）</button><button data-native-action="disableAutoCapture">关闭收藏跟随</button><button data-native-action="autoCaptureDiagnostics">查看检测记录</button><button data-native-action="calibrateAutoCapture">适配本机按钮</button></div><p class="help">首次需在系统无障碍中开启「拾光 · 收藏跟随（试用）」。如提示受限设置，到系统应用信息的更多菜单允许受限设置，再回来开启。同时检测点击和“未收藏→已收藏”变化。B站需先完成原收藏夹确认。系统拦截弹窗时点“选择分类”提示；无反应可查看本机检测记录。YouTube 使用“保存到播放列表/稍后观看”，完成原平台确认后再采集。图标未识别时可点“适配本机按钮”，按提示记录收藏或保存图标。日常点击分享不会触发拾光；只有确认收藏后才会自动取链接。不同版本可能无法识别；识别不等于已保存。</p><h3 class="subheading">小红书标题与封面</h3><p class="help">如果收藏只有短链域名或默认封面，小红书可能要求网页登录。你可以在本机登录一次，再自动补全已有收藏；凭据不上传拾光云端。App 里的登录状态与此网页登录独立。</p><div class="data-actions"><button data-native-action="xhsMetadataLogin">登录小红书补全信息</button><button data-native-action="xhsMetadataDisable">关闭小红书网页授权</button></div>`:''}<h3 class="subheading">备份与迁移</h3><p class="help">JSON 备份包含标题、链接、标签、笔记和阅读状态。在另一台电脑导入即可迁移；重复链接保留现有内容。</p><div class="data-actions"><button id="export-data">导出 JSON 备份</button><button id="import-data">导入文件</button><button id="show-demo">浏览示例知识库</button></div><hr class="section-rule"><h3 class="subheading">清空本地知识库</h3><p class="help">删除此浏览器中的真实收藏，不会影响原平台。建议先导出备份。</p><button class="danger" id="clear-data">清空所有真实收藏…</button>`);document.querySelectorAll('[data-native-action]').forEach(button=>button.onclick=()=>{try{window.ShiguangNative.postMessage(JSON.stringify({action:button.dataset.nativeAction}))}catch{toast('请更新拾光 App 后重试')}});$('#export-data').onclick=backup;$('#import-data').onclick=importDialog;$('#show-demo').onclick=()=>{demo=true;resetFilters();closeModal();render()};$('#clear-data').onclick=()=>{openModal('清空之前，再确认一下',`<p class="help">即将删除 ${items.length} 条真实收藏。这一步无法撤销。输入「清空」继续。</p><label class="field">确认文字<input id="clear-confirm" autocomplete="off"></label><div class="modal-actions"><button class="outline" id="backup-clear">先导出备份</button><button class="primary" id="confirm-clear">确认清空</button></div>`);$('#backup-clear').onclick=backup;$('#confirm-clear').onclick=()=>{if($('#clear-confirm').value!=='清空'){toast('请输入「清空」确认');return}items=[];demo=false;save();closeModal();resetFilters();render();toast('已清空本地收藏')}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view],[data-platform],[data-tag],[data-detail],[data-edit],[data-star],[data-read],[data-delete]');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;state.platform='all';state.tag='all'}if(b.dataset.platform){state.platform=b.dataset.platform;state.view='all';state.tag='all'}if(b.dataset.tag!==undefined)state.tag=b.dataset.tag;if(b.dataset.edit){const x=data().find(x=>x.id===b.dataset.edit);if(x)form(x);return}if(b.dataset.delete){confirmDelete(b.dataset.delete);return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.dataset.star||b.dataset.read){const x=data().find(x=>x.id===(b.dataset.star||b.dataset.read));if(x){if(b.dataset.star)x.starred=!x.starred;else x.read=!x.read;if(!demo)save();else toast('已更新示例，真实知识库未受影响')}}render()});
$('#search').oninput=e=>{state.q=e.target.value;render()};$('#sort').onchange=e=>{state.sort=e.target.value;render()};$('#type-filter').onchange=e=>{state.type=e.target.value;render()};$('#grid-view').onclick=()=>{list=false;$('#grid-view').classList.add('active');$('#list-view').classList.remove('active');render()};$('#list-view').onclick=()=>{list=true;$('#list-view').classList.add('active');$('#grid-view').classList.remove('active');render()};['#add-side','#empty-add'].forEach(s=>$(s).onclick=()=>form());['#sources-side','#sources-top'].forEach(s=>$(s).onclick=sources);['#backup-top'].forEach(s=>$(s).onclick=backup);$('#settings-side').onclick=settings;$('#leave-demo').onclick=()=>{demo=false;save();resetFilters();render()};$('#empty-demo').onclick=()=>{demo=true;resetFilters();render()};$('#random-read').onclick=()=>{const unread=data().filter(x=>!x.read),pool=unread.length?unread:data();if(!pool.length){toast('先收下一条收藏，再来随机重逢');return}detail(pool[Math.floor(Math.random()*pool.length)].id)};$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#search').focus()}});function refreshCaptured(){if($('#modal').open)return;try{const raw=localStorage.getItem(KEY);if(raw===null)return;const parsed=JSON.parse(raw);if(!Array.isArray(parsed))return;items=parsed.map(SG.normalize).filter(Boolean);persistedIds=new Set(items.map(x=>x.id));demo=false;render()}catch{toast('知识库读取失败，请先备份检查')}}window.addEventListener('storage',e=>{if(e.key===KEY){refreshCaptured();window.dispatchEvent(new Event('shiguang-local-change'))}});window.addEventListener('shiguang-refresh',refreshCaptured);window.addEventListener('focus',refreshCaptured);render();if(storageFailed)toast('原存储数据异常，尚未覆盖。请先在数据管理中检查或备份。');

$('#settings-top').onclick=settings;$('#mobile-platform').innerHTML='<option value="all">所有来源</option>'+Object.entries(P).map(([k,p])=>`<option value="${k}">${p.name}</option>`).join('');$('#mobile-platform').onchange=e=>{state.platform=e.target.value;state.tag='all';render()};$('#mobile-view').onchange=e=>{state.view=e.target.value;render()};

