const shared=new URLSearchParams(location.search);
if(SG.safeUrl(shared.get('url'))){
 form();
 $('#item-form input[name="url"]').value=shared.get('url');
 $('#item-form input[name="title"]').value=(shared.get('title')||'').slice(0,500);
 $('#item-form textarea[name="notes"]').value=(shared.get('note')||'').slice(0,5000);
 try{history.replaceState(null,'',location.pathname)}catch{}
}

$('#filter-toggle').onclick=()=>{const expanded=$('#filter-toggle').getAttribute('aria-expanded')!=='true';$('#filter-toggle').setAttribute('aria-expanded',String(expanded));document.querySelector('.toolbar').classList.toggle('filters-open',expanded);};


async function pasteLink(){
 try{let text='';if(window.ShiguangNative){text=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('请长按链接输入框粘贴')),3000);ShiguangNative.onmessage=event=>{clearTimeout(timer);try{resolve(JSON.parse(event.data).clipboard||'');}catch{reject(Error('无法读取剪贴板'));}};ShiguangNative.postMessage(JSON.stringify({action:'paste'}));});}else text=await navigator.clipboard.readText();
 const link=text.match(/https?:\/\/[^\s<>"，。；）】]+/)?.[0];if(!SG.safeUrl(link))throw Error('剪贴板中没有网页链接');$('#item-form input[name="url"]').value=link;const title=$('#item-form input[name="title"]');if(!title.value)title.value=text.replace(link,'').trim().slice(0,500)||new URL(link).hostname;
 }catch(error){$('#form-error').textContent=error.message||'请长按链接输入框粘贴';}
}
document.addEventListener('error',event=>{if(event.target.matches?.('.cover-image'))event.target.remove();},true);
let fillingCovers=false,coverTimer;const coverAttempts=new Map();
function queueCoverFill(){clearTimeout(coverTimer);coverTimer=setTimeout(fillCovers,300);}
async function fillCovers(){
 if(fillingCovers||demo||!window.ShiguangPreview)return;fillingCovers=true;
 try{
 const owner=localStorage.getItem('shiguang.cloud.owner')||'';
 const pending=items.filter(x=>(!x.thumbnail||ShiguangPreview.needsTitle(x))&&(SG.thumbnailFor(x)||(owner||window.ShiguangPreviewNative)&&ShiguangPreview.supported(x.url))&&Date.now()-(coverAttempts.get(owner+x.url)||0)>3600000).slice(0,30);
 for(const original of pending){
  if((localStorage.getItem('shiguang.cloud.owner')||'')!==owner||demo)break;
  coverAttempts.set(owner+original.url,Date.now());let meta;try{meta=await ShiguangPreview.fetch(original);}catch{continue;}
  const current=items.find(x=>x.id===original.id&&x.url===original.url);if(!current||demo||(localStorage.getItem('shiguang.cloud.owner')||'')!==owner)continue;
  if(ShiguangPreview.apply(current,meta)&&save()){if(!$('#modal').open)render();}
 }
 }finally{fillingCovers=false;}
}
window.addEventListener('shiguang-cloud-status',queueCoverFill);window.addEventListener('shiguang-local-change',queueCoverFill);queueCoverFill();
window.addEventListener('shiguang-preview-ready',()=>{coverAttempts.clear();queueCoverFill();});

$('.brand').onclick=e=>{e.preventDefault();resetFilters();render();window.scrollTo({top:0,behavior:'smooth'})};
